// Geschiedenissen (nt-2). Zie docs/BIJBELREIS.md, "De 150 geschiedenissen".
// Nummers 100–117 (Markus 6 t/m Lukas 19). Reisstappen in public/bijbelreis/inhoud/nt-jezus-2.js.
// Getoetst met scripts/bijbel-controle/nt-2.txt (Statenvertaling).
BR.geschiedenissen = BR.geschiedenissen || [];
BR.kernwoorden = BR.kernwoorden || {};

BR.geschiedenissen.push(
{ nr: 100, t: "Herodes en Johannes de Doper", ref: "Markus 6:14–29", sectie: "galilea",
  stappen: ["jezus-2:nt-brood-en-berg:0"], vorm: "plek",
  uitleg: "Koning Herodes, de viervorst van Galilea, hoort over de wonderen van de Heere Jezus. Hij is bang dat Johannes de Doper uit de doden is opgestaan. Herodes had Johannes gevangengezet, omdat Johannes hem eerlijk zei dat hij niet met Herodias mocht leven, de vrouw van zijn broer Filippus. Herodes wist dat Johannes een rechtvaardig en heilig man was, en hij luisterde zelfs graag naar hem. Maar Herodias wilde Johannes doden. Op het verjaardagsfeest van Herodes danst haar dochter, en Herodes belooft haar met een eed alles wat ze vraagt. Op aanraden van haar moeder vraagt ze het hoofd van Johannes de Doper. Herodes wordt zeer bedroefd, maar vanwege zijn eden en zijn gasten laat hij Johannes in de gevangenis onthoofden.",
  betekenis: "Johannes bleef de waarheid zeggen, ook tegen een koning, en betaalde dat met zijn leven. De Heere Jezus zei over hem: ‘onder degenen, die van vrouwen geboren zijn, is niemand opgestaan meerder dan Johannes de Doper’ (Mattheüs 11:11).",
  wie: ["Herodes Antipas", "Herodias", "Johannes de Doper"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Het is u niet geoorloofd de huisvrouw uws broeders te hebben.", "Johannes de Doper", ["Herodes", "Herodias"]],
    ["Eis van mij, wat gij ook wilt, en ik zal het u geven.", "Herodes", ["Herodias", "Johannes de Doper"]],
    ["Het hoofd van Johannes den Doper.", "Herodias", ["Herodes", "de discipelen van Johannes"]],
    ["Deze is Johannes, dien ik onthoofd heb; die is van de doden opgewekt.", "Herodes", ["Herodias", "Filippus"]]] },
  quiz: [
    { q: "Waarom schrok Herodes toen hij over de Heere Jezus hoorde?", a: ["Hij dacht dat Johannes de Doper was opgestaan", "Hij dacht dat de Romeinen kwamen", "Hij dacht dat Mozes was teruggekomen"], why: "Markus 6:16" },
    { q: "Met wie was Herodias eerst getrouwd?", a: ["Met Filippus, de broer van Herodes", "Met de keizer", "Met Johannes"], why: "Markus 6:17" },
    { q: "Wat wist Herodes eigenlijk van Johannes?", a: ["Dat hij een rechtvaardig en heilig man was", "Dat hij een bedrieger was", "Niets, hij kende hem niet"], why: "Markus 6:20" },
    { q: "Waarom liet Herodes Johannes toch onthoofden?", a: ["Vanwege zijn eden en zijn gasten", "Omdat Johannes wilde vluchten", "Omdat de Romeinen het eisten"], why: "Markus 6:26" }],
  cross: [["Lukas 3:19–20", "Johannes had Herodes bestraft om Herodias en om al het kwaad dat hij deed; daarom sloot Herodes hem op."],
    ["Mattheüs 14:12–13", "De discipelen van Johannes begroeven hem en vertelden het aan de Heere Jezus; Hij ging toen met een schip naar een eenzame plaats."],
    ["Lukas 23:8", "Bij het verhoor van de Heere Jezus zag Herodes Hem eindelijk, en hoopte hij een teken te zien."]],
  tl: [28, 29], tijd: "ca. 28–29 n.Chr. (of 31–32)",
  tijdNoot: "Reconstructie. Markus vertelt de dood van Johannes als terugblik, vlak voor de spijziging van de vijfduizend, kort voor een Pascha (Johannes 6:4). Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 28–29; wie 33 n.Chr. aanhoudt, op ca. 31–32. De Bijbel noemt geen jaartal." },

{ nr: 101, t: "Vijfduizend mannen eten", ref: "Johannes 6:1–15", sectie: "galilea",
  stappen: ["jezus-2:nt-brood-en-berg:1", "jezus-2:nt-brood-en-berg:2", "jezus-2:nt-brood-en-berg:3"], vorm: "plek",
  uitleg: "De Heere Jezus gaat naar de overkant van het meer van Galilea, en een grote menigte volgt Hem, omdat ze Zijn tekenen bij de zieken gezien hebben. Het is kort voor het Pascha. Om Filippus op de proef te stellen, vraagt Hij waar ze brood kunnen kopen; Hij wist zelf al wat Hij zou doen. Filippus rekent uit dat tweehonderd penningen brood niet genoeg is, en Andreas wijst op een jongen met vijf gerstebroden en twee visjes. De Heere Jezus laat ongeveer vijfduizend mannen in het gras gaan zitten, dankt, en laat het eten uitdelen, zoveel als iedereen wil. Er blijven twaalf korven met brokken over, want er mag niets verloren gaan. De mensen zeggen: ‘Deze is waarlijk de Profeet, Die in de wereld komen zou’, en willen Hem koning maken, maar Hij gaat alleen de berg op. De volgende dag legt Hij in Kapernaüm uit waar dit teken op wijst: ‘Ik ben het Brood des levens.’",
  betekenis: "Het teken wijst naar de Heere Jezus Zelf: zoals brood het lichaam voedt, geeft Hij het eeuwige leven aan wie in Hem gelooft (Johannes 6:35, 47–51).",
  wie: ["Jezus", "Filippus", "Andreas"],
  ontdek: { soort: "koppel", titel: "Welk getal hoort erbij?", paren: [
    ["Broden van de jongen", "5"], ["Visjes", "2"], ["Mannen die aten", "omtrent 5000"], ["Korven met brokken", "12"], ["Penningen brood: niet genoeg", "200"]] },
  quiz: [
    { q: "Welke discipel stelde de Heere Jezus op de proef met de vraag waar ze brood moesten kopen?", a: ["Filippus", "Petrus", "Judas"], why: "Johannes 6:5–6" },
    { q: "Wat voor broden had de jongen?", a: ["Gerstebroden", "Tarwebroden", "Ongezuurde koeken"], why: "Johannes 6:9" },
    { q: "Wat deed de Heere Jezus voordat Hij het brood uitdeelde?", a: ["Hij dankte", "Hij brak het in twaalf stukken", "Hij vroeg wie honger had"], why: "Johannes 6:11" },
    { q: "Waarom ging de Heere Jezus na de maaltijd alleen de berg op?", a: ["De mensen wilden Hem met geweld koning maken", "Hij wilde vissen", "Hij was moe van het lopen"], why: "Johannes 6:15" }],
  cross: [["2 Koningen 4:42–44", "Elisa liet honderd mannen eten van twintig gerstebroden, en er bleef over."],
    ["Exodus 16:15", "Over het manna zei Mozes: ‘Dit is het brood, hetwelk de HEERE ulieden te eten gegeven heeft.’"],
    ["Johannes 6:35", "‘Ik ben het Brood des levens; die tot Mij komt, zal geenszins hongeren.’"],
    ["Lukas 9:10–17", "Lukas vertelt dat het gebeurde in een woeste plaats bij de stad Bethsaïda."]],
  tl: [29, 29], tijd: "ca. 29 n.Chr. (of 32)",
  tijdNoot: "Reconstructie. Johannes 6:4: het Pascha was nabij. Dat is waarschijnlijk een jaar vóór het Pascha waarop de Heere Jezus stierf (Johannes 11:55). Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29; wie 33 n.Chr. aanhoudt, op ca. 32." },

{ nr: 102, t: "De zieke man bij Bethesda", ref: "Johannes 5:1–18", sectie: "galilea",
  stappen: ["jezus-2:nt-feesten-jeruzalem:0", "jezus-2:nt-feesten-jeruzalem:1"], vorm: "plek",
  uitleg: "Voor een feest van de Joden gaat de Heere Jezus naar Jeruzalem. Bij de Schaapspoort is het badwater Bethesda, met vijf zuilengangen vol zieken, blinden en kreupelen die wachten tot het water bewogen wordt. Daar ligt een man die al achtendertig jaar ziek is, en hij heeft niemand die hem in het water helpt. De Heere Jezus vraagt: ‘Wilt gij gezond worden?’ en zegt: ‘Sta op, neem uw beddeken op, en wandel.’ Meteen is de man gezond. Omdat het sabbat is, krijgt hij te horen dat hij zijn matje niet mag dragen. Later vindt de Heere Jezus hem in de tempel en waarschuwt hem: ‘Zondig niet meer.’ De Joden willen de Heere Jezus doden, omdat Hij dit op de sabbat deed en God Zijn eigen Vader noemde.",
  betekenis: "De Heere Jezus zegt: ‘Mijn Vader werkt tot nu toe, en Ik werk ook’ (Johannes 5:17). Hij laat zien dat Hij de Zoon is, Die net als de Vader levend maakt (Johannes 5:21).",
  wie: ["Jezus", "Zieke man"],
  ontdek: { soort: "onthul", titel: "Wat weet je van Bethesda?", items: [
    ["Waar?", "Bij de Schaapspoort in Jeruzalem (Johannes 5:2)."],
    ["Hoe groot?", "Het badwater had vijf zalen of zuilengangen (Johannes 5:2)."],
    ["Hoe lang ziek?", "Achtendertig jaar (Johannes 5:5)."],
    ["Welke dag?", "Het was sabbat (Johannes 5:9)."],
    ["Opgegraven", "Bij de St.-Annakerk in Jeruzalem zijn twee grote baden gevonden; daar wordt Bethesda meestal gezocht. Dat is archeologie, niet uit de Bijbel."]] },
  quiz: [
    { q: "Bij welke poort van Jeruzalem lag Bethesda?", a: ["De Schaapspoort", "De Vispoort", "De Waterpoort"], why: "Johannes 5:2" },
    { q: "Wat vroeg de Heere Jezus aan de zieke man?", a: ["Wilt gij gezond worden?", "Gelooft gij dit?", "Hoe heet gij?"], why: "Johannes 5:6" },
    { q: "Waar vond de Heere Jezus de man later terug?", a: ["In de tempel", "Bij het badwater", "In zijn huis"], why: "Johannes 5:14" },
    { q: "Waarom wilden de Joden de Heere Jezus doden?", a: ["Hij genas op de sabbat en noemde God Zijn eigen Vader", "Hij had geen belasting betaald", "Hij had de tempel beschadigd"], why: "Johannes 5:18" }],
  cross: [["Jeremia 17:21", "‘Draagt geen last op den sabbatdag.’"],
    ["Johannes 7:23", "De Heere Jezus verdedigt dat Hij ‘een gehelen mens gezond gemaakt heb op den sabbat’."],
    ["Johannes 5:24", "‘Die Mijn woord hoort, en gelooft Hem, Die Mij gezonden heeft, die heeft het eeuwige leven.’"]],
  tl: [28, 28], tijd: "ca. 28 n.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker. Johannes 5:1 noemt ‘een feest der Joden’ zonder te zeggen welk. Johannes vertelt het vóór de spijziging van de vijfduizend (Pascha, ca. 29 n.Chr. als de kruisiging in 30 was). Wie de kruisiging in 33 n.Chr. stelt, schuift alles drie jaar op." },

{ nr: 103, t: "De blindgeborene", ref: "Johannes 9", sectie: "galilea",
  stappen: ["jezus-2:nt-feesten-jeruzalem:2", "jezus-2:nt-feesten-jeruzalem:3"], vorm: "plek", kw: "sabbat",
  uitleg: "De Heere Jezus ziet een man die blind geboren is. De discipelen vragen wie er gezondigd heeft, hij of zijn ouders. De Heere Jezus zegt: geen van beiden, maar de werken van God moeten in hem zichtbaar worden; ‘zolang Ik in de wereld ben, zo ben Ik het Licht der wereld.’ Hij maakt slijk, strijkt dat op de ogen van de blinde, en stuurt hem naar het badwater Siloam. Daar wast de man zich, en hij kan zien. Omdat het sabbat is, ondervragen de Farizeeën hem en zijn ouders; sommigen zeggen: ‘Deze Mens is van God niet, want Hij houdt den sabbat niet.’ De man blijft eerlijk: ‘Een ding weet ik, dat ik blind was, en nu zie.’ Ze zetten hem uit de synagoge, maar de Heere Jezus zoekt hem op, en de man zegt: ‘Ik geloof, Heere!’",
  betekenis: "De Heere Jezus is het Licht der wereld (Johannes 9:5; 8:12). De blinde gaat zien, maar wie zegt ‘wij zien’ en de Heere Jezus niet aanneemt, blijft in zijn zonde (Johannes 9:39–41).",
  wie: ["Jezus", "Blindgeborene", "Ouders", "Farizeeën"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Rabbi, wie heeft er gezondigd, deze, of zijn ouders?", "De discipelen", ["De Farizeeën", "De buren"]],
    ["Hij heeft zijn ouderdom, vraagt hemzelven.", "De ouders", ["De discipelen", "De Heere Jezus"]],
    ["Een ding weet ik, dat ik blind was, en nu zie.", "De genezen man", ["Bartimeüs", "Een Farizeeër"]],
    ["Gelooft gij in den Zoon van God?", "De Heere Jezus", ["Een Farizeeër", "De vader van de man"]]] },
  quiz: [
    { q: "Hoe heette het badwater waar de blinde zich moest wassen?", a: ["Siloam", "Bethesda", "De Jordaan"], why: "Johannes 9:7" },
    { q: "Wat betekent de naam Siloam?", a: ["Uitgezonden", "Licht", "Levend water"], why: "Johannes 9:7" },
    { q: "Wat zei de genezen man eerst over de Heere Jezus tegen de Farizeeën?", a: ["Hij is een Profeet", "Hij is een zondaar", "Ik ken Hem niet"], why: "Johannes 9:17" },
    { q: "Wat deden de Farizeeën ten slotte met de man?", a: ["Ze wierpen hem uit", "Ze gaven hem een beloning", "Ze maakten hem leraar in de synagoge"], why: "Johannes 9:34" },
    { q: "Wat deed de man nadat hij zei: ‘Ik geloof, Heere!’?", a: ["Hij aanbad de Heere Jezus", "Hij ging naar huis", "Hij ging naar de priester"], why: "Johannes 9:38" }],
  cross: [["Jesaja 35:5", "‘Alsdan zullen der blinden ogen opengedaan worden.’"],
    ["Johannes 8:12", "‘Ik ben het licht der wereld; die Mij volgt, zal in de duisternis niet wandelen.’"],
    ["Johannes 11:37", "Bij het graf van Lazarus herinneren mensen zich Hem ‘Die de ogen des blinden geopend heeft’."]],
  tl: [29, 29], tijd: "ca. 29 n.Chr. (of 32)",
  tijdNoot: "Reconstructie. Johannes 9 volgt op het Loofhuttenfeest (Johannes 7:2) en komt vóór het feest van de vernieuwing in de winter (Johannes 10:22): het najaar vóór het laatste Pascha. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29; wie 33 n.Chr. aanhoudt, op ca. 32." },

{ nr: 104, t: "De goede Herder", ref: "Johannes 10:1–30", sectie: "galilea",
  stappen: ["jezus-2:nt-feesten-jeruzalem:4", "jezus-2:nt-feesten-jeruzalem:5"], vorm: "gelijkenis",
  uitleg: "Na de genezing van de blindgeborene spreekt de Heere Jezus nog tegen de Farizeeën die zeiden: ‘Wij zien’ (Johannes 9:40–41). Hij vertelt hun een gelijkenis: een dief klimt ergens anders over de muur van de schaapskooi, maar de herder gaat door de deur naar binnen. Hij roept zijn schapen bij hun naam, gaat voor ze uit, en ze volgen hem omdat ze zijn stem kennen. Zij begrijpen niet wat Hij bedoelt (Johannes 10:6). Daarom legt de Heere Jezus het uit: ‘Ik ben de Deur der schapen’ en ‘Ik ben de goede Herder; de goede herder stelt zijn leven voor de schapen.’ Een huurling vlucht als de wolf komt, maar Hij legt Zijn leven af, en neemt het weer terug. Op het feest van de vernieuwing zegt Hij: ‘Mijn schapen horen Mijn stem, en Ik ken dezelve, en zij volgen Mij’, en niemand zal ze uit Zijn hand rukken.",
  betekenis: "In het Oude Testament wordt God de Herder van Zijn volk genoemd, en Hij beloofde één Herder te verwekken (Psalm 23:1; Ezechiël 34:23). De Heere Jezus zegt dat Hij die goede Herder is, Die Zijn leven geeft voor de schapen (Johannes 10:11, 15).",
  wie: ["Jezus", "Farizeeën"],
  ontdek: { soort: "gelijkenis", titel: "Wat betekenen de beelden?", beelden: [
    ["De deur", "‘Ik ben de Deur; indien iemand door Mij ingaat, die zal behouden worden.’", "Johannes 10:9"],
    ["De goede herder", "De Heere Jezus, Die Zijn leven geeft voor de schapen.", "Johannes 10:11"],
    ["De huurling", "Iemand voor wie de schapen niet van hemzelf zijn; hij vlucht als de wolf komt.", "Johannes 10:12–13"],
    ["De stem van de herder", "Zijn schapen horen Zijn stem en volgen Hem.", "Johannes 10:27"],
    ["Andere schapen", "Schapen ‘die van dezen stal niet zijn’: ook die moet Hij toebrengen, tot één kudde en één Herder.", "Johannes 10:16"]] },
  quiz: [
    { q: "Waaraan kennen de schapen de herder?", a: ["Aan zijn stem", "Aan zijn kleren", "Aan zijn staf"], why: "Johannes 10:4" },
    { q: "Wat doet de huurling als de wolf komt?", a: ["Hij vlucht", "Hij vecht tegen de wolf", "Hij roept de herder"], why: "Johannes 10:12" },
    { q: "Begrepen de toehoorders de gelijkenis meteen?", a: ["Nee, ze verstonden niet wat Hij bedoelde", "Ja, ze begrepen het meteen", "Ze lachten erom"], why: "Johannes 10:6" },
    { q: "Wat geeft de Heere Jezus aan Zijn schapen?", a: ["Het eeuwige leven", "Gras en water", "Een nieuwe stal"], why: "Johannes 10:28" }],
  cross: [["Psalm 23:1", "‘De HEERE is mijn Herder, mij zal niets ontbreken.’"],
    ["Ezechiël 34:23", "God belooft: ‘Ik zal een enigen Herder over hen verwekken.’"],
    ["Jesaja 40:11", "‘Hij zal Zijn kudde weiden gelijk een herder; Hij zal de lammeren in Zijn armen vergaderen.’"],
    ["1 Petrus 2:25", "‘Gij waart als dwalende schapen; maar gij zijt nu bekeerd tot den Herder en Opziener uwer zielen.’"]],
  tl: [29, 29], tijd: "ca. 29 n.Chr. (of 32)",
  tijdNoot: "Reconstructie. De woorden over de goede Herder volgen op Johannes 9 (najaar) en lopen door tot het feest van de vernieuwing in de winter (Johannes 10:22). Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29; wie 33 n.Chr. aanhoudt, op ca. 32." },

{ nr: 105, t: "Petrus belijdt: Gij zijt de Christus", ref: "Mattheüs 16:13–28", sectie: "galilea",
  stappen: ["jezus-2:nt-brood-en-berg:4", "jezus-2:nt-brood-en-berg:5"], vorm: "plek",
  uitleg: "In de streek van Caesarea Filippi vraagt de Heere Jezus Zijn discipelen wie de mensen zeggen dat Hij is. Sommigen zeggen Johannes de Doper, anderen Elia, en anderen Jeremia of een van de profeten. Dan vraagt Hij: ‘Maar gij, wie zegt gij, dat Ik ben?’ Simon Petrus antwoordt: ‘Gij zijt de Christus, de Zoon des levenden Gods.’ De Heere Jezus noemt hem zalig, want niet mensen, maar de Vader in de hemel heeft hem dat geopenbaard. Hij zegt: ‘gij zijt Petrus, en op deze petra zal Ik Mijn gemeente bouwen, en de poorten der hel zullen dezelve niet overweldigen.’ Daarna begint Hij te vertellen dat Hij in Jeruzalem moet lijden, gedood worden en op de derde dag opgewekt worden. Als Petrus dat wil tegenhouden, zegt de Heere Jezus: ‘Ga weg achter Mij, satanas!’ Wie Hem wil volgen, moet zichzelf verloochenen, zijn kruis opnemen en Hem volgen.",
  betekenis: "Petrus belijdt wie de Heere Jezus is: de Christus, de door God beloofde Gezalfde, de Zoon van God (Mattheüs 16:16). Direct daarna maakt de Heere Jezus duidelijk dat de Christus moet lijden en sterven, en op de derde dag opgewekt worden (Mattheüs 16:21).",
  wie: ["Jezus", "Petrus"],
  ontdek: { soort: "kaart", titel: "Waar was het?", vraag: "Petrus zei het in het uiterste noorden van het land, bij de bronnen van de Jordaan. Wijs Caesarea Filippi aan.", id: "nt_kaesareafilippi", v: "kanaan" },
  quiz: [
    { q: "Wie zeiden sommige mensen dat de Heere Jezus was?", a: ["Johannes de Doper, Elia of Jeremia", "Mozes of Aäron", "Een engel uit de hemel"], why: "Mattheüs 16:14" },
    { q: "Wie had aan Petrus geopenbaard dat Jezus de Christus is?", a: ["De Vader in de hemelen", "Zijn broer Andreas", "Johannes de Doper"], why: "Mattheüs 16:17" },
    { q: "Waarom zei de Heere Jezus tegen Petrus: ‘Ga weg achter Mij, satanas’?", a: ["Petrus wilde niet dat Hij zou lijden", "Petrus had Hem verloochend", "Petrus was in slaap gevallen"], why: "Mattheüs 16:22–23" },
    { q: "Wat moet iemand doen die achter de Heere Jezus aan wil komen?", a: ["Zichzelf verloochenen, zijn kruis opnemen en Hem volgen", "Eerst rijk worden", "Naar Jeruzalem verhuizen"], why: "Mattheüs 16:24" }],
  cross: [["Johannes 6:68–69", "Ook in Kapernaüm had Petrus gezegd: ‘wij hebben geloofd en bekend, dat Gij zijt de Christus’."],
    ["Johannes 1:42–43", "Andreas vond de Messias, ‘de Christus’; de Heere Jezus gaf Simon de naam Cefas, ‘hetwelk overgezet wordt Petrus’."],
    ["1 Petrus 2:6", "Petrus schrijft later over Christus als de uitverkoren Hoeksteen in Sion."],
    ["Lukas 24:6–7", "Na de opstanding herinneren de engelen aan Zijn woorden over lijden en opstaan."]],
  tl: [29, 29], tijd: "ca. 29 n.Chr. (of 32)",
  tijdNoot: "Reconstructie. De belijdenis van Petrus komt na de spijziging (vlak voor een Pascha, Johannes 6:4) en vóór de laatste reis naar Jeruzalem. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29; wie 33 n.Chr. aanhoudt, op ca. 32." },

{ nr: 106, t: "De verheerlijking op de berg", ref: "Lukas 9:28–36", sectie: "galilea",
  stappen: ["jezus-2:nt-brood-en-berg:6"], vorm: "plek",
  uitleg: "Ongeveer acht dagen na de belijdenis van Petrus neemt de Heere Jezus Petrus, Johannes en Jakobus mee een berg op om te bidden. Terwijl Hij bidt, verandert Zijn gezicht, en Zijn kleren worden wit en stralend. Mozes en Elia verschijnen in heerlijkheid en spreken met Hem over Zijn uitgang, die Hij in Jeruzalem zou volbrengen. De discipelen zijn zwaar van de slaap, maar als ze wakker worden, zien ze Zijn heerlijkheid. Petrus zegt: ‘Meester, het is goed, dat wij hier zijn’, en wil drie tenten maken; hij weet niet wat hij zegt. Dan overschaduwt een wolk hen, en uit de wolk klinkt een stem: ‘Deze is Mijn geliefde Zoon; hoort Hem!’ Daarna is de Heere Jezus weer alleen, en de discipelen vertellen in die dagen aan niemand wat ze gezien hebben.",
  betekenis: "God de Vader Zelf wijst op Zijn Zoon: ‘hoort Hem!’ (Lukas 9:35). Mozes en Elia spreken met Hem over Zijn sterven in Jeruzalem (Lukas 9:31); de heerlijkheid op de berg komt vlak na de aankondiging van Zijn lijden.",
  wie: ["Jezus", "Petrus", "Jakobus", "Johannes", "Mozes", "Elia"],
  ontdek: { soort: "verbanden", titel: "Beloofd en uitgekomen", items: [
    ["Deuteronomium 18:15", "Mozes zei: God zal een Profeet als ik verwekken; ‘naar Hem zult gij horen’.", "Lukas 9:35", "Op de berg zegt God over Jezus: ‘Deze is Mijn geliefde Zoon; hoort Hem!’"],
    ["Lukas 9:31", "Mozes en Elia spreken over Zijn uitgang, die Hij in Jeruzalem zou volbrengen.", "Lukas 24:6–7", "Hij werd overgeleverd en gekruisigd, en stond op de derde dag op."],
    ["Mattheüs 17:9", "‘Zegt niemand dit gezicht, totdat de Zoon des mensen zal opgestaan zijn uit de doden.’", "2 Petrus 1:16–18", "Later schrijft Petrus: wij hebben die stem gehoord, toen wij met Hem op de heilige berg waren."]] },
  quiz: [
    { q: "Welke drie discipelen gingen mee de berg op?", a: ["Petrus, Johannes en Jakobus", "Andreas, Filippus en Thomas", "Petrus, Andreas en Judas"], why: "Lukas 9:28" },
    { q: "Waarom ging de Heere Jezus de berg op?", a: ["Om te bidden", "Om te slapen", "Om voor de mensen te vluchten"], why: "Lukas 9:28" },
    { q: "Waarover spraken Mozes en Elia met de Heere Jezus?", a: ["Over Zijn uitgang in Jeruzalem", "Over de bouw van de tempel", "Over de Romeinen"], why: "Lukas 9:31" },
    { q: "Wat zei de stem uit de wolk?", a: ["Deze is Mijn geliefde Zoon; hoort Hem!", "Gaat heen in vrede", "Bouwt hier drie tenten"], why: "Lukas 9:35" }],
  cross: [["Mattheüs 17:1–8", "Mattheüs: ‘na zes dagen’, op een hoge berg; Zijn aangezicht blonk als de zon."],
    ["2 Petrus 1:16–18", "Petrus: wij hebben die stem gehoord op de heilige berg."],
    ["Exodus 34:29", "Ook het gezicht van Mozes glansde toen hij van de berg Sinaï afkwam."]],
  tl: [29, 29], tijd: "ca. 29 n.Chr. (of 32)",
  tijdNoot: "Reconstructie. Lukas zegt ‘omtrent acht dagen’ na de belijdenis van Petrus (Lukas 9:28). Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29; wie 33 n.Chr. aanhoudt, op ca. 32." },

{ nr: 107, t: "De kinderen en de rijke jongeman", ref: "Markus 10:13–31", sectie: "galilea",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:7", "jezus-2:nt-reis-naar-jeruzalem:8"], vorm: "plek",
  uitleg: "Aan de overkant van de Jordaan brengen mensen kleine kinderen bij de Heere Jezus, zodat Hij hen zou aanraken. De discipelen wijzen hen af, maar de Heere Jezus wordt daar boos om: ‘Laat de kinderkens tot Mij komen, en verhindert ze niet; want derzulken is het Koninkrijk Gods.’ Wie het Koninkrijk van God niet ontvangt zoals een kind, komt er niet in. Hij neemt de kinderen in Zijn armen en zegent hen. Daarna valt een man voor Hem op de knieën en vraagt wat hij moet doen om het eeuwige leven te beërven; hij zegt dat hij de geboden van jongs af gehouden heeft. De Heere Jezus kijkt hem aan, heeft hem lief en zegt: ‘Een ding ontbreekt u’: verkoop alles, geef het aan de armen en volg Mij. De man gaat bedroefd weg, want hij heeft veel bezittingen. De Heere Jezus zegt dat het voor rijken heel moeilijk is om in het Koninkrijk van God te komen: ‘Bij de mensen is het onmogelijk, maar niet bij God; want alle dingen zijn mogelijk bij God.’",
  betekenis: "Het Koninkrijk van God ontvang je zoals een kind (Markus 10:15). Wie op zijn bezit vertrouwt, komt er moeilijk in; zalig worden is bij mensen onmogelijk, maar niet bij God (Markus 10:24, 27).",
  wie: ["Jezus", "Kinderen", "Rijke jongeman"],
  ontdek: { soort: "onthul", titel: "Tik om te ontdekken", items: [
    ["Wie werden gebracht?", "Kleine kinderen, ‘kinderkens’, om door de Heere Jezus aangeraakt te worden (Markus 10:13)."],
    ["Wat deed Hij met hen?", "Hij nam ze in Zijn armen, legde hun de handen op en zegende ze (Markus 10:16)."],
    ["Jong of oud?", "Mattheüs noemt de rijke man een jongeling (Mattheüs 19:20); Lukas noemt hem een overste (Lukas 18:18)."],
    ["Een kemel en een naald", "‘Het is lichter, dat een kemel ga door het oog van een naald, dan dat een rijke in het Koninkrijk Gods inga’ (Markus 10:25)."],
    ["Honderdvoud", "Wie iets verlaat om de Heere Jezus en het Evangelie, ontvangt honderdvoud, ‘met de vervolgingen’, en in de toekomende eeuw het eeuwige leven (Markus 10:29–30)."]] },
  quiz: [
    { q: "Hoe reageerde de Heere Jezus toen de discipelen de kinderen wegstuurden?", a: ["Hij nam het zeer kwalijk", "Hij gaf de discipelen gelijk", "Hij ging weg"], why: "Markus 10:14" },
    { q: "Wat zei de Heere Jezus dat de rijke man moest doen?", a: ["Alles verkopen, het de armen geven en Hem volgen", "Meer bidden", "Vaker naar de tempel gaan"], why: "Markus 10:21" },
    { q: "Waarom ging de rijke man bedroefd weg?", a: ["Hij had vele goederen", "Hij was ziek", "Hij was te laat"], why: "Markus 10:22" },
    { q: "Wat is volgens de Heere Jezus nog moeilijker dan een kemel door het oog van een naald?", a: ["Dat een rijke in het Koninkrijk Gods ingaat", "Dat een visser rijk wordt", "Dat een kind de wet leert"], why: "Markus 10:25" }],
  cross: [["Mattheüs 18:3", "‘Indien gij u niet verandert, en wordt gelijk de kinderkens, zo zult gij in het Koninkrijk der hemelen geenszins ingaan.’"],
    ["Mattheüs 19:20–22", "Mattheüs vertelt dat het een jongeling was."],
    ["Mattheüs 6:19–20", "‘Vergadert u schatten in den hemel.’"]],
  tl: [30, 30], tijd: "ca. 30 n.Chr. (of 33)",
  tijdNoot: "Reconstructie. Markus 10 beschrijft de laatste reis naar Jeruzalem, kort voor het Pascha waarop de Heere Jezus stierf. Wie de kruisiging ca. 30 n.Chr. stelt, komt op het begin van 30; wie 33 n.Chr. aanhoudt, op het begin van 33." },

{ nr: 108, t: "Jakobus en Johannes vragen de beste plaatsen", ref: "Markus 10:32–45", sectie: "galilea",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:9"], vorm: "plek",
  uitleg: "Op weg naar Jeruzalem loopt de Heere Jezus voorop, en de discipelen zijn verbaasd en bang. Hij neemt de twaalf apart en vertelt opnieuw wat er gaat gebeuren: Hij zal overgeleverd worden aan de overpriesters en schriftgeleerden, ter dood veroordeeld, bespot, gegeseld en gedood, en op de derde dag zal Hij opstaan. Juist dan komen Jakobus en Johannes, de zonen van Zebedeüs, met een verzoek: ze willen in Zijn heerlijkheid naast Hem zitten, de een rechts en de ander links. De Heere Jezus zegt: ‘Gij weet niet, wat gij begeert. Kunt gij den drinkbeker drinken, dien Ik drink?’ ‘Wij kunnen’, zeggen ze. Hij antwoordt dat ze Zijn beker inderdaad zullen drinken, maar dat de plaatsen naast Hem gegeven worden aan wie ze bereid zijn. De andere tien worden boos, en de Heere Jezus roept hen bij Zich: wie groot wil worden, moet dienaar zijn, en wie de eerste wil zijn, dienstknecht van allen. ‘Want ook de Zoon des mensen is niet gekomen, om gediend te worden, maar om te dienen, en Zijn ziel te geven tot een rantsoen voor velen.’",
  betekenis: "In Gods Koninkrijk is de grootste wie dient. De Heere Jezus geeft Zelf het voorbeeld: Hij kwam om te dienen en Zijn leven te geven als losprijs (‘rantsoen’) voor velen (Markus 10:45).",
  wie: ["Jezus", "Jakobus", "Johannes"],
  ontdek: { soort: "koppel", titel: "Wat hoort erbij?", paren: [
    ["De oversten van de volken", "voeren heerschappij over hen"],
    ["Wie groot wil worden", "zal uw dienaar zijn"],
    ["Wie de eerste wil zijn", "zal aller dienstknecht zijn"],
    ["De Zoon des mensen", "kwam om te dienen en Zijn ziel te geven"]] },
  quiz: [
    { q: "Wiens zonen waren Jakobus en Johannes?", a: ["Van Zebedeüs", "Van Jonas", "Van Timeüs"], why: "Markus 10:35" },
    { q: "Wat vroegen Jakobus en Johannes?", a: ["Om rechts en links naast Hem te zitten in Zijn heerlijkheid", "Om de beurs van de discipelen te dragen", "Om in de tempel te mogen preken"], why: "Markus 10:37" },
    { q: "Hoe reageerden de andere tien discipelen?", a: ["Ze namen het Jakobus en Johannes zeer kwalijk", "Ze vroegen hetzelfde", "Ze zeiden niets"], why: "Markus 10:41" },
    { q: "Waarvoor is de Zoon des mensen gekomen?", a: ["Om te dienen en Zijn ziel te geven tot een rantsoen voor velen", "Om gediend te worden", "Om koning van Rome te worden"], why: "Markus 10:45" }],
  cross: [["Mattheüs 20:20–21", "Volgens Mattheüs kwam hun moeder met hen mee om dit te vragen."],
    ["Handelingen 12:2", "Jakobus werd later met het zwaard gedood: hij dronk de beker van het lijden."],
    ["Johannes 13:14–15", "De Heere Jezus wast de voeten van Zijn discipelen: ‘Ik heb u een voorbeeld gegeven.’"],
    ["Lukas 9:54–55", "Eerder wilden Jakobus en Johannes vuur uit de hemel laten komen op een dorp van de Samaritanen."]],
  tl: [30, 30], tijd: "ca. 30 n.Chr. (of 33)",
  tijdNoot: "Reconstructie. Dit gebeurt op de laatste reis naar Jeruzalem, vlak voor Jericho (Markus 10:46), kort voor het Pascha waarop de Heere Jezus stierf. Wie de kruisiging ca. 30 n.Chr. stelt, komt op het begin van 30; wie 33 n.Chr. aanhoudt, op het begin van 33." },

{ nr: 109, t: "De barmhartige Samaritaan", ref: "Lukas 10:25–37", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:1"], vorm: "gelijkenis",
  uitleg: "Een wetgeleerde wil de Heere Jezus op de proef stellen en vraagt hoe hij het eeuwige leven kan beërven. Hij kent het antwoord uit de wet: God liefhebben met heel je hart, ziel, kracht en verstand, en je naaste als jezelf. ‘Doe dat, en gij zult leven’, zegt de Heere Jezus. Maar de wetgeleerde wil zichzelf rechtvaardigen en vraagt: ‘En wie is mijn naaste?’ (Lukas 10:29). Als antwoord vertelt de Heere Jezus een gelijkenis. Een man reist van Jeruzalem naar Jericho; hij wordt overvallen, uitgekleed, geslagen en halfdood achtergelaten. Een priester en een Leviet zien hem liggen en lopen aan de overkant voorbij. Maar een Samaritaan krijgt medelijden: hij verbindt de wonden met olie en wijn, zet de man op zijn eigen rijdier, brengt hem naar een herberg en betaalt de waard twee penningen om voor hem te zorgen. Als de wetgeleerde moet zeggen dat de naaste is ‘die barmhartigheid aan hem gedaan heeft’, zegt de Heere Jezus: ‘Ga heen, en doe gij desgelijks.’",
  betekenis: "De wetgeleerde vroeg wie zijn naaste was; de Heere Jezus draait de vraag om: wie is de naaste geworden van iemand in nood? (Lukas 10:36–37). Zo wordt het gebod uit de wet concreet: ‘gij zult uw naaste liefhebben als uzelven’ (Leviticus 19:18).",
  wie: ["Jezus", "Wetgeleerde"],
  ontdek: { soort: "volgorde", titel: "Wie kwam er langs?", items: ["Een man wordt overvallen", "Een priester gaat voorbij", "Een Leviet gaat voorbij", "Een Samaritaan verbindt zijn wonden", "De waard krijgt twee penningen"] },
  quiz: [
    { q: "Wat vroeg de wetgeleerde eerst?", a: ["Wat moet ik doen om het eeuwige leven te beërven?", "Wie is de grootste in het Koninkrijk?", "Mag ik op de sabbat genezen?"], why: "Lukas 10:25" },
    { q: "Van welke stad naar welke stad reisde de man in de gelijkenis?", a: ["Van Jeruzalem naar Jericho", "Van Nazareth naar Kapernaüm", "Van Bethlehem naar Hebron"], why: "Lukas 10:30" },
    { q: "Wat goot de Samaritaan in de wonden?", a: ["Olie en wijn", "Water en zout", "Honing"], why: "Lukas 10:34" },
    { q: "Hoeveel penningen gaf de Samaritaan aan de waard?", a: ["Twee", "Tien", "Dertig"], why: "Lukas 10:35" }],
  cross: [["Leviticus 19:18", "‘Gij zult uw naaste liefhebben als uzelven; Ik ben de HEERE!’"],
    ["Deuteronomium 6:5", "‘Zo zult gij den HEERE, uw God, liefhebben, met uw ganse hart.’"],
    ["Johannes 4:9", "‘De Joden houden geen gemeenschap met de Samaritanen.’"],
    ["Lukas 6:36", "‘Weest dan barmhartig, gelijk ook uw Vader barmhartig is.’"]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas plaatst deze gelijkenis op de reis naar Jeruzalem (vanaf Lukas 9:51), zonder datum en zonder plaatsnaam. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 110, t: "Martha en Maria", ref: "Lukas 10:38–42", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:2"], vorm: "plek", kw: "liefde",
  uitleg: "Op de reis komt de Heere Jezus in een dorp, en Martha ontvangt Hem in haar huis. Haar zuster Maria gaat aan Zijn voeten zitten en luistert naar Zijn woord. Martha heeft het erg druk met het vele werk om alles klaar te maken. Ze komt naar de Heere Jezus en vraagt of het Hem niets kan schelen dat haar zuster haar alleen laat werken: ‘Zeg dan haar, dat zij mij helpe.’ Maar de Heere Jezus antwoordt: ‘Martha, Martha, gij bekommert en ontrust u over vele dingen; maar een ding is nodig.’ Maria heeft het goede deel gekozen, en dat zal haar niet worden afgenomen. Johannes vertelt dat de Heere Jezus Martha, haar zuster en Lazarus liefhad (Johannes 11:5).",
  betekenis: "Dit verhaal staat direct na het grote gebod om God lief te hebben met heel je hart, en je naaste als jezelf (Lukas 10:27). Maria zit aan Zijn voeten en hoort Zijn woord: dat noemt de Heere Jezus ‘het goede deel’ (Lukas 10:42).",
  wie: ["Jezus", "Martha", "Maria van Bethanië"],
  ontdek: { soort: "onthul", titel: "De familie uit Bethanië", items: [
    ["Martha", "Ze ontving de Heere Jezus in haar huis en was druk met dienen (Lukas 10:38, 40). Later diende ze weer bij een maaltijd in Bethanië (Johannes 12:2)."],
    ["Maria", "Ze zat aan de voeten van de Heere Jezus en hoorde Zijn woord (Lukas 10:39). Later zalfde ze Zijn voeten met kostbare nardus (Johannes 12:3)."],
    ["Lazarus", "Hun broer. De Heere Jezus wekte hem op uit de doden (Johannes 11:43–44)."],
    ["Het dorp", "Lukas noemt het ‘een vlek’; Johannes noemt Bethanië ‘het vlek van Maria en haar zuster Martha’ (Johannes 11:1)."]] },
  quiz: [
    { q: "Wie ontving de Heere Jezus in haar huis?", a: ["Martha", "Maria", "Maria Magdalena"], why: "Lukas 10:38" },
    { q: "Wat deed Maria?", a: ["Ze zat aan de voeten van de Heere Jezus en hoorde Zijn woord", "Ze bakte brood", "Ze ging water halen"], why: "Lukas 10:39" },
    { q: "Wat vroeg Martha aan de Heere Jezus?", a: ["Of Hij tegen Maria wilde zeggen dat ze moest helpen", "Of Hij wilde blijven slapen", "Of Hij haar broer wilde genezen"], why: "Lukas 10:40" },
    { q: "Hoeveel dingen zijn volgens de Heere Jezus nodig?", a: ["Eén ding", "Twee dingen", "Tien dingen"], why: "Lukas 10:42" }],
  cross: [["Lukas 10:27", "Het grote gebod: God liefhebben met heel je hart, en je naaste als jezelf."],
    ["Psalm 27:4", "‘Een ding heb ik van den HEERE begeerd, dat zal ik zoeken.’"],
    ["Johannes 11:5", "‘Jezus nu had Martha, en haar zuster, en Lazarus lief.’"],
    ["Johannes 12:2–3", "Martha diende; Maria zalfde de voeten van de Heere Jezus."]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas vertelt dit op de reis naar Jeruzalem (vanaf Lukas 9:51), zonder datum. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 111, t: "Het grote avondmaal", ref: "Lukas 14:15–24", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:3"], vorm: "gelijkenis",
  uitleg: "Op een sabbat is de Heere Jezus te gast bij een van de oversten van de Farizeeën. Hij geneest daar een zieke man, en spreekt over gasten die de beste plaatsen kiezen en over wie je moet uitnodigen. Dan zegt een van de gasten: ‘Zalig is hij, die brood eet in het Koninkrijk Gods’ (Lukas 14:15). Daarop vertelt de Heere Jezus deze gelijkenis. Iemand geeft een groot avondmaal en nodigt veel mensen uit. Als alles klaar is, laat hij zeggen: ‘Komt, want alle dingen zijn nu gereed.’ Maar ze hebben allemaal een excuus: de een heeft een akker gekocht, de ander vijf juk ossen, en een derde is net getrouwd. Dan wordt de heer boos en laat hij armen, verminkten, kreupelen en blinden uit de straten van de stad binnenhalen, en daarna ook mensen van de wegen en heggen, zodat zijn huis vol wordt. Niemand van de mannen die eerst genodigd waren, zal van zijn avondmaal proeven.",
  betekenis: "Met deze gelijkenis antwoordt de Heere Jezus op de uitroep over het eten in het Koninkrijk van God (Lukas 14:15). De eerste genodigden slaan de uitnodiging af en komen er niet in; armen en mensen van buiten worden binnengehaald (Lukas 14:21–24).",
  wie: ["Jezus", "Farizeeën"],
  ontdek: { soort: "koppel", titel: "Wie zei wat?", paren: [
    ["De eerste genodigde", "Ik heb een akker gekocht"],
    ["Een ander", "Ik heb vijf juk ossen gekocht"],
    ["Nog een ander", "Ik heb een vrouw getrouwd"],
    ["Uit de straten van de stad", "Armen, verminkten, kreupelen en blinden"],
    ["Van de wegen en heggen", "Nog meer gasten, tot het huis vol is"]] },
  quiz: [
    { q: "Bij wie at de Heere Jezus op die sabbat?", a: ["Bij een van de oversten van de Farizeeën", "Bij Zacheüs", "Bij Martha"], why: "Lukas 14:1" },
    { q: "Wat liet de heer tegen de genodigden zeggen?", a: ["Komt, want alle dingen zijn nu gereed", "Blijft maar thuis", "Neemt zelf eten mee"], why: "Lukas 14:17" },
    { q: "Waarom kon de derde genodigde niet komen?", a: ["Hij had een vrouw getrouwd", "Hij was ziek", "Hij had een akker gekocht"], why: "Lukas 14:20" },
    { q: "Waar moest de knecht als laatste mensen halen?", a: ["Op de wegen en bij de heggen", "In de tempel", "In het paleis van de koning"], why: "Lukas 14:23" }],
  cross: [["Mattheüs 22:2–3", "Een verwante gelijkenis: een koning geeft een bruiloft voor zijn zoon, en de genodigden willen niet komen."],
    ["Jesaja 25:6", "‘De HEERE der heirscharen zal op dezen berg allen volken een vetten maaltijd maken.’"],
    ["Openbaring 19:9", "‘Zalig zijn zij, die geroepen zijn tot het avondmaal van de bruiloft des Lams.’"]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas vertelt dit op de reis naar Jeruzalem, zonder datum en zonder plaatsnaam. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 112, t: "De verloren zoon", ref: "Lukas 15:11–32", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:4"], vorm: "gelijkenis",
  uitleg: "Tollenaars en zondaars komen naar de Heere Jezus om naar Hem te luisteren, en de Farizeeën en schriftgeleerden mopperen: ‘Deze ontvangt de zondaars, en eet met hen’ (Lukas 15:1–2). Daarom vertelt Hij drie gelijkenissen; de derde gaat over een vader met twee zonen. De jongste vraagt zijn deel van de erfenis, vertrekt naar een ver land en verkwist daar alles met een losbandig leven. Als er hongersnood komt, moet hij zwijnen hoeden, en hij zou zelfs graag van hun voer eten. Dan komt hij tot zichzelf: ik zal opstaan, naar mijn vader gaan en zeggen dat ik gezondigd heb. Zijn vader ziet hem al van ver, krijgt medelijden, rent naar hem toe en kust hem. Hij laat het beste kleed, een ring en schoenen brengen en het gemeste kalf slachten: ‘deze mijn zoon was dood, en is weder levend geworden.’ Maar de oudste zoon wordt boos en wil niet naar binnen; de vader gaat naar buiten en smeekt hem: ‘Kind, gij zijt altijd bij mij, en al het mijne is uwe.’",
  betekenis: "De Heere Jezus zegt zelf waar de gelijkenissen van Lukas 15 over gaan: er is blijdschap in de hemel over één zondaar die zich bekeert (Lukas 15:7, 10). De mopperende oudste zoon lijkt op de Farizeeën, die mopperden dat Hij zondaars ontving (Lukas 15:2, 28–30).",
  wie: ["Jezus", "Tollenaars", "Farizeeën"],
  ontdek: { soort: "gelijkenis", titel: "Verloren en gevonden", beelden: [
    ["Het verloren schaap", "‘Er zal blijdschap zijn in den hemel over een zondaar, die zich bekeert.’", "Lukas 15:7"],
    ["De verloren penning", "‘Er is blijdschap voor de engelen Gods over een zondaar, die zich bekeert.’", "Lukas 15:10"],
    ["De jongste zoon", "‘Deze mijn zoon was dood, en is weder levend geworden; en hij was verloren, en is gevonden!’", "Lukas 15:24"],
    ["De oudste zoon", "Hij wordt boos en wil niet naar binnen, zoals de Farizeeën mopperden dat de Heere Jezus zondaars ontving.", "Lukas 15:2, 28"]] },
  quiz: [
    { q: "Waarom mopperden de Farizeeën en schriftgeleerden?", a: ["De Heere Jezus ontving zondaars en at met hen", "De Heere Jezus genas op de sabbat", "De discipelen wasten hun handen niet"], why: "Lukas 15:2" },
    { q: "Hoeveel schapen had de herder in de eerste gelijkenis?", a: ["Honderd", "Tien", "Negenennegentig"], why: "Lukas 15:4" },
    { q: "Wat wilde de jongste zoon tegen zijn vader zeggen?", a: ["Vader, ik heb gezondigd tegen den Hemel, en voor u", "Vader, geef mij nog meer geld", "Vader, het was niet mijn schuld"], why: "Lukas 15:18" },
    { q: "Wat deed de vader toen hij zijn zoon van ver zag aankomen?", a: ["Hij liep naar hem toe, viel hem om de hals en kuste hem", "Hij deed de deur op slot", "Hij stuurde een knecht met eten"], why: "Lukas 15:20" },
    { q: "Wat liet de vader slachten?", a: ["Het gemeste kalf", "Een bokje", "Een lam"], why: "Lukas 15:23" }],
  cross: [["Psalm 103:13", "‘Gelijk zich een vader ontfermt over de kinderen, ontfermt Zich de HEERE over degenen, die Hem vrezen.’"],
    ["Jesaja 55:7", "‘Hij bekere zich tot den HEERE, zo zal Hij Zich Zijner ontfermen.’"],
    ["Lukas 19:10", "‘De Zoon des mensen is gekomen, om te zoeken en zalig te maken, dat verloren was.’"]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas vertelt deze gelijkenissen op de reis naar Jeruzalem, zonder datum en zonder plaatsnaam. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 113, t: "Tien melaatsen", ref: "Lukas 17:11–19", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:5"], vorm: "plek", kw: "dankbaarheid",
  uitleg: "Op weg naar Jeruzalem trekt de Heere Jezus door het midden van Samaria en Galilea. Bij een dorp komen tien melaatse mannen Hem tegemoet. Ze blijven op afstand staan en roepen: ‘Jezus, Meester! ontferm U onzer!’ Hij zegt dat ze zich aan de priesters moeten laten zien. Terwijl ze op weg zijn, worden ze rein. Eén van hen keert terug zodra hij ziet dat hij genezen is; hij eert God met luide stem en valt voor de Heere Jezus op zijn gezicht om Hem te danken. Die man is een Samaritaan. De Heere Jezus vraagt: ‘Zijn niet de tien gereinigd geworden, en waar zijn de negen?’ Tegen de man zegt Hij: ‘Sta op, en ga heen; uw geloof heeft u behouden.’",
  betekenis: "Alle tien werden rein, maar alleen één kwam terug om God de eer te geven, en dat was een vreemdeling (Lukas 17:17–18). In de Psalmen staat: ‘Wie dankoffert, die zal Mij eren’ (Psalm 50:23).",
  wie: ["Jezus", "Melaatsen", "Samaritaan"],
  ontdek: { soort: "volgorde", titel: "Wat gebeurde er?", items: ["Tien melaatsen roepen van verre", "De Heere Jezus stuurt hen naar de priesters", "Onderweg worden ze rein", "Eén keert terug en eert God", "Hij valt aan Jezus' voeten en dankt Hem"] },
  quiz: [
    { q: "Waar stonden de melaatsen toen ze riepen?", a: ["Van verre", "Vlak bij de Heere Jezus", "Op het dak van een huis"], why: "Lukas 17:12" },
    { q: "Naar wie moesten de melaatsen gaan?", a: ["Naar de priesters", "Naar de Jordaan om zich te wassen", "Naar hun familie"], why: "Lukas 17:14" },
    { q: "Wanneer werden ze rein?", a: ["Terwijl ze heengingen", "Toen de Heere Jezus hen aanraakte", "Na zeven dagen"], why: "Lukas 17:14" },
    { q: "Uit welk volk kwam de man die terugkwam?", a: ["Hij was een Samaritaan", "Hij was een Romein", "Hij was een Leviet"], why: "Lukas 17:16" }],
  cross: [["Leviticus 13:45–46", "Een melaatse moest ‘Onrein, onrein!’ roepen en buiten het leger wonen."],
    ["2 Koningen 5:14", "Ook Naäman, een vreemdeling uit Syrië, werd van melaatsheid gereinigd."],
    ["Psalm 103:2", "‘Loof den HEERE, mijn ziel, en vergeet geen van Zijn weldaden.’"]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas vertelt dit op de reis naar Jeruzalem (Lukas 17:11), zonder datum. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 114, t: "De Farizeeër en de tollenaar", ref: "Lukas 18:9–14", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:6"], vorm: "gelijkenis",
  uitleg: "De Heere Jezus vertelt deze gelijkenis aan sommige mensen die op zichzelf vertrouwden dat ze rechtvaardig waren, en de anderen niets waard vonden (Lukas 18:9). Twee mannen gaan naar de tempel om te bidden: een Farizeeër en een tollenaar. De Farizeeër staat daar en dankt God dat hij niet is zoals andere mensen: rovers, onrechtvaardigen, overspelers, of zoals die tollenaar. Hij vast twee keer per week en geeft tienden van alles wat hij bezit. De tollenaar blijft op afstand staan. Hij durft zelfs niet naar de hemel op te kijken, slaat op zijn borst en bidt: ‘O God! wees mij zondaar genadig!’ De Heere Jezus zegt: deze tollenaar ging gerechtvaardigd naar huis, en de Farizeeër niet. ‘Want een ieder, die zichzelven verhoogt, zal vernederd worden, en die zichzelven vernedert, zal verhoogd worden.’",
  betekenis: "Niet wie zichzelf rechtvaardig vindt, maar wie zijn zonde belijdt en om genade vraagt, gaat volgens de Heere Jezus gerechtvaardigd naar huis (Lukas 18:14). ‘God wederstaat de hovaardigen, maar de nederigen geeft Hij genade’ (1 Petrus 5:5).",
  wie: ["Jezus"],
  ontdek: { soort: "wiezei", titel: "Wie bad zo?", items: [
    ["O God! ik dank U, dat ik niet ben gelijk de anderen mensen.", "De Farizeeër", ["De tollenaar", "Zacheüs"]],
    ["Ik vast tweemaal per week; ik geef tienden van alles, wat ik bezit.", "De Farizeeër", ["De tollenaar", "De wetgeleerde"]],
    ["O God! wees mij zondaar genadig!", "De tollenaar", ["De Farizeeër", "De priester"]]] },
  quiz: [
    { q: "Aan wie vertelde de Heere Jezus deze gelijkenis?", a: ["Aan mensen die op zichzelf vertrouwden dat ze rechtvaardig waren", "Aan de tollenaars", "Aan de kinderen"], why: "Lukas 18:9" },
    { q: "Hoe vaak per week vastte de Farizeeër?", a: ["Twee keer", "Eén keer", "Elke dag"], why: "Lukas 18:12" },
    { q: "Wat deed de tollenaar toen hij bad?", a: ["Hij sloeg op zijn borst", "Hij hief zijn handen hoog op", "Hij ging vooraan staan"], why: "Lukas 18:13" },
    { q: "Wie ging volgens de Heere Jezus gerechtvaardigd naar huis?", a: ["De tollenaar", "De Farizeeër", "Allebei"], why: "Lukas 18:14" }],
  cross: [["Psalm 51:19", "‘Een gebroken en verslagen hart zult Gij, o God! niet verachten.’"],
    ["1 Petrus 5:5", "‘God wederstaat de hovaardigen, maar de nederigen geeft Hij genade.’"],
    ["Lukas 14:11", "Dezelfde woorden: wie zichzelf verhoogt, zal vernederd worden."]],
  tl: [29, 30], tijd: "ca. 29–30 n.Chr. (of 32–33)",
  tijdNoot: "Reconstructie. Lukas vertelt deze gelijkenis op de reis naar Jeruzalem, zonder datum en zonder plaatsnaam. Wie de kruisiging ca. 30 n.Chr. stelt, komt op ca. 29–30; wie 33 n.Chr. aanhoudt, op ca. 32–33." },

{ nr: 115, t: "Lazarus wordt opgewekt", ref: "Johannes 11:1–46", sectie: "onderweg",
  stappen: ["jezus-2:nt-feesten-jeruzalem:6", "jezus-2:nt-feesten-jeruzalem:7", "jezus-2:nt-feesten-jeruzalem:8"], vorm: "route",
  uitleg: "Lazarus uit Bethanië, de broer van Martha en Maria, wordt ziek. De zusters laten het de Heere Jezus weten, maar Hij blijft nog twee dagen waar Hij is, aan de overkant van de Jordaan (Johannes 10:40). Hij zegt dat deze ziekte is ‘ter heerlijkheid Gods’, en daarna zegt Hij duidelijk: ‘Lazarus is gestorven.’ Als Hij in Bethanië komt, ligt Lazarus al vier dagen in het graf. Tegen Martha zegt Hij: ‘Ik ben de Opstanding en het Leven; die in Mij gelooft zal leven, al ware hij ook gestorven.’ Martha antwoordt: ‘Ja, Heere; ik heb geloofd, dat Gij zijt de Christus, de Zone Gods.’ Als Hij Maria en de anderen ziet huilen, wordt Hij diep bewogen, en ‘Jezus weende’. Bij het graf laat Hij de steen wegnemen, dankt Zijn Vader en roept: ‘Lazarus, kom uit!’ En de gestorvene komt naar buiten, met handen en voeten in grafdoeken gewikkeld.",
  betekenis: "De Heere Jezus heeft macht over de dood: Hij is ‘de Opstanding en het Leven’ (Johannes 11:25). Juist na dit wonder besluit de raad Hem te doden (Johannes 11:53); Kajafas zei, niet uit zichzelf, dat Hij zou sterven voor het volk (Johannes 11:50–51).",
  wie: ["Jezus", "Lazarus", "Martha", "Maria van Bethanië", "Thomas", "Kajafas"],
  ontdek: { soort: "volgorde", titel: "Zet het verhaal op volgorde", items: ["De zusters sturen bericht", "De Heere Jezus blijft nog twee dagen", "Martha gaat Hem tegemoet", "Jezus weende", "De steen wordt weggenomen", "Lazarus, kom uit!"] },
  quiz: [
    { q: "Hoe lang bleef de Heere Jezus nog waar Hij was, nadat Hij hoorde dat Lazarus ziek was?", a: ["Twee dagen", "Een week", "Geen dag"], why: "Johannes 11:6" },
    { q: "Welke discipel zei: ‘Laat ons ook gaan, opdat wij met Hem sterven’?", a: ["Thomas", "Petrus", "Johannes"], why: "Johannes 11:16" },
    { q: "Wat zei de Heere Jezus tegen Martha?", a: ["Ik ben de Opstanding en het Leven", "Ik ben het Licht der wereld", "Ik ben de Deur der schapen"], why: "Johannes 11:25" },
    { q: "Wat had Lazarus om zijn gezicht toen hij uit het graf kwam?", a: ["Een zweetdoek", "Een gouden band", "Niets"], why: "Johannes 11:44" },
    { q: "Naar welke stad trok de Heere Jezus Zich daarna terug?", a: ["Efraïm", "Kapernaüm", "Jericho"], why: "Johannes 11:54" }],
  cross: [["Johannes 12:1–2", "Zes dagen voor het Pascha eet de Heere Jezus in Bethanië, en Lazarus zit mee aan tafel."],
    ["Johannes 12:10–11", "De overpriesters willen ook Lazarus doden, omdat velen door hem in Jezus gingen geloven."],
    ["Johannes 5:28–29", "‘De ure komt, in dewelke allen, die in de graven zijn, Zijn stem zullen horen.’"],
    ["Johannes 18:14", "Johannes herinnert aan de raad van Kajafas: ‘dat het nut was, dat een Mens voor het volk stierve’."]],
  tl: [30, 30], tijd: "ca. 30 n.Chr. (of 33)",
  tijdNoot: "Reconstructie. Na dit wonder was ‘het pascha der Joden nabij’ (Johannes 11:55): het gebeurde weken vóór het laatste Pascha. Wie de kruisiging ca. 30 n.Chr. stelt, komt op het begin van 30; wie 33 n.Chr. aanhoudt, op het begin van 33." },

{ nr: 116, t: "De blinde Bartimeüs", ref: "Markus 10:46–52", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:10"], vorm: "plek",
  uitleg: "De Heere Jezus komt met Zijn discipelen in Jericho, op weg naar Jeruzalem. Als Hij met een grote menigte de stad weer uitgaat, zit Bartimeüs, de blinde zoon van Timeüs, langs de weg te bedelen. Als hij hoort dat Jezus van Nazareth voorbijkomt, roept hij: ‘Jezus, Gij Zone Davids! ontferm U mijner.’ Veel mensen willen dat hij zijn mond houdt, maar hij roept nog harder. De Heere Jezus blijft staan en laat hem roepen: ‘Heb goeden moed; sta op; Hij roept u.’ Bartimeüs gooit zijn mantel af, staat op en komt bij de Heere Jezus. Hij vraagt wat hij wil, en Bartimeüs zegt: ‘Rabboni! dat ik ziende mag worden.’ ‘Ga heen, uw geloof heeft u behouden’, zegt de Heere Jezus; meteen kan Bartimeüs zien, en hij volgt Hem op de weg.",
  betekenis: "Bartimeüs noemt de Heere Jezus ‘Zone Davids’: de Koning uit het huis van David, Die God beloofd had (2 Samuël 7:12–13). Zijn roepen wordt gehoord, en hij volgt de Heere Jezus (Markus 10:47, 52).",
  wie: ["Jezus", "Bartimeüs"],
  ontdek: { soort: "kaart", titel: "Waar zat Bartimeüs?", vraag: "Bartimeüs zat langs de weg bij Jericho, de laatste stad op weg naar Jeruzalem. Wijs Jericho aan.", id: "jericho", v: "kanaan" },
  quiz: [
    { q: "Hoe heette de vader van Bartimeüs?", a: ["Timeüs", "Zebedeüs", "Jonas"], why: "Markus 10:46" },
    { q: "Hoe noemde Bartimeüs de Heere Jezus toen hij riep?", a: ["Zoon van David", "Meester uit Kapernaüm", "Profeet Elia"], why: "Markus 10:47" },
    { q: "Wat gooide Bartimeüs af toen hij geroepen werd?", a: ["Zijn mantel", "Zijn stok", "Zijn sandalen"], why: "Markus 10:50" },
    { q: "Wat deed Bartimeüs nadat hij kon zien?", a: ["Hij volgde de Heere Jezus op de weg", "Hij ging terug naar huis", "Hij ging naar de tempel"], why: "Markus 10:52" }],
  cross: [["Lukas 18:35–43", "Lukas vertelt over een blinde bij Jericho, toen de Heere Jezus dicht bij de stad kwam."],
    ["Mattheüs 20:29–30", "Mattheüs vertelt over twee blinden, toen ze uit Jericho gingen."],
    ["Jesaja 35:5", "‘Alsdan zullen der blinden ogen opengedaan worden.’"]],
  tl: [30, 30], tijd: "ca. 30 n.Chr. (of 33)",
  tijdNoot: "Reconstructie. Jericho is de laatste stad op de weg naar Jeruzalem, vlak voor het laatste Pascha. Wie de kruisiging ca. 30 n.Chr. stelt, komt op het voorjaar van 30; wie 33 n.Chr. aanhoudt, op het voorjaar van 33." },

{ nr: 117, t: "Zacheüs", ref: "Lukas 19:1–10", sectie: "onderweg",
  stappen: ["jezus-2:nt-reis-naar-jeruzalem:11"], vorm: "plek", kw: "evangelie",
  uitleg: "De Heere Jezus gaat door Jericho. Daar woont Zacheüs, een rijke man die de baas is over de tollenaars. Hij wil graag zien wie Jezus is, maar hij is klein en kan niet over de menigte heen kijken. Daarom rent hij vooruit en klimt in een wilde vijgenboom langs de weg. Als de Heere Jezus daar komt, kijkt Hij omhoog en zegt: ‘Zacheüs! haast u, en kom af; want Ik moet heden in uw huis blijven.’ Zacheüs komt snel naar beneden en ontvangt Hem blij. Maar alle mensen die het zien, mopperen dat Hij bij een zondaar gaat logeren. Zacheüs zegt: ‘Zie, de helft van mijn goederen, Heere, geef ik den armen’, en wie hij door bedrog iets heeft afgenomen, krijgt het vier keer terug. De Heere Jezus zegt: ‘Heden is dezen huize zaligheid geschied ... Want de Zoon des mensen is gekomen, om te zoeken en zalig te maken, dat verloren was.’",
  betekenis: "Hier zegt de Heere Jezus Zelf waarvoor Hij kwam: ‘om te zoeken en zalig te maken, dat verloren was’ (Lukas 19:10). Dat is de goede boodschap, het Evangelie. Zacheüs' leven verandert: hij geeft weg en maakt goed wat hij fout deed (Lukas 19:8).",
  wie: ["Jezus", "Zacheüs"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Zacheüs! haast u, en kom af; want Ik moet heden in uw huis blijven.", "De Heere Jezus", ["Zacheüs", "Een tollenaar"]],
    ["Hij is tot een zondigen man ingegaan, om te herbergen.", "De mensen die het zagen", ["De discipelen", "Zacheüs"]],
    ["Zie, de helft van mijn goederen, Heere, geef ik den armen.", "Zacheüs", ["De rijke jongeman", "Een Farizeeër"]],
    ["De Zoon des mensen is gekomen, om te zoeken en zalig te maken, dat verloren was.", "De Heere Jezus", ["Johannes de Doper", "Petrus"]]] },
  quiz: [
    { q: "Wat was Zacheüs?", a: ["Een overste van de tollenaars", "Een visser", "Een priester"], why: "Lukas 19:2" },
    { q: "Waarom kon Zacheüs de Heere Jezus niet zien?", a: ["Hij was klein en de menigte stond ervoor", "Hij was blind", "Hij zat in de gevangenis"], why: "Lukas 19:3" },
    { q: "In wat voor boom klom Zacheüs?", a: ["Een wilde vijgenboom", "Een olijfboom", "Een palmboom"], why: "Lukas 19:4" },
    { q: "Hoeveel keer wilde Zacheüs teruggeven wat hij door bedrog had gekregen?", a: ["Vier keer", "Twee keer", "Zeven keer"], why: "Lukas 19:8" }],
  cross: [["Exodus 22:1", "De wet: wie een schaap stal, moest er vier teruggeven."],
    ["Ezechiël 34:16", "God zegt: ‘Het verlorene zal Ik zoeken.’"],
    ["Lukas 15:2", "Ook daar mopperen mensen dat de Heere Jezus zondaars ontvangt."],
    ["Mattheüs 9:13", "‘Ik ben niet gekomen om te roepen rechtvaardigen, maar zondaars tot bekering.’"]],
  tl: [30, 30], tijd: "ca. 30 n.Chr. (of 33)",
  tijdNoot: "Reconstructie. Vanuit Jericho gaat de Heere Jezus op naar Jeruzalem voor het laatste Pascha (Lukas 19:28). Wie de kruisiging ca. 30 n.Chr. stelt, komt op het voorjaar van 30; wie 33 n.Chr. aanhoudt, op het voorjaar van 33." },
);

BR.kernwoorden.sabbat = { n: "Sabbat",
  uitleg: "De sabbat is de zevende dag van de week, de rustdag. God rustte op de zevende dag van al Zijn werk, en Hij zegende en heiligde die dag (Genesis 2:2–3). In de tien geboden zegt God: ‘Gedenkt den sabbatdag, dat gij dien heiligt’ (Exodus 20:8). De Heere Jezus genas op de sabbat en zei: ‘De sabbat is gemaakt om den mens, niet de mens om den sabbat’; Hij is ‘een Heere ook van den sabbat’ (Markus 2:27–28). De eerste christenen kwamen samen op de eerste dag van de week, de dag waarop de Heere Jezus was opgestaan (Johannes 20:1; Handelingen 20:7).",
  refs: [["Genesis 2:2–3", "God rustte op de zevende dag, en zegende en heiligde die."],
    ["Exodus 20:8–11", "Het gebod: zes dagen werken, de zevende dag is de sabbat van de HEERE."],
    ["Markus 2:27–28", "De Zoon des mensen is Heere ook van de sabbat."],
    ["Johannes 9:14", "Het was sabbat toen de Heere Jezus de ogen van de blindgeborene opende."]] };

BR.kernwoorden.liefde = { n: "Liefde",
  uitleg: "Liefde begint bij God: ‘Want alzo lief heeft God de wereld gehad, dat Hij Zijn eniggeboren Zoon gegeven heeft’ (Johannes 3:16). Het grote gebod is God liefhebben met heel je hart, ziel, kracht en verstand, en je naaste als jezelf (Lukas 10:27). De Heere Jezus had Martha, Maria en Lazarus lief (Johannes 11:5), en Hij zei: niemand heeft meer liefde dan wie zijn leven geeft voor zijn vrienden (Johannes 15:13). ‘Wij hebben Hem lief, omdat Hij ons eerst liefgehad heeft’ (1 Johannes 4:19).",
  refs: [["Lukas 10:27", "God liefhebben met heel je hart, en je naaste als jezelf."],
    ["Johannes 3:16", "God gaf Zijn Zoon, omdat Hij de wereld liefhad."],
    ["Johannes 15:13", "Niemand heeft meer liefde dan wie zijn leven geeft voor zijn vrienden."],
    ["1 Johannes 4:19", "Wij hebben God lief, omdat Hij ons eerst liefhad."]] };

BR.kernwoorden.dankbaarheid = { n: "Dankbaarheid",
  uitleg: "Dankbaar zijn is God eren voor wat Hij gegeven heeft. ‘Loof den HEERE, mijn ziel, en vergeet geen van Zijn weldaden’ (Psalm 103:2). Van de tien melaatsen kwam er maar één terug om God de eer te geven en de Heere Jezus te danken (Lukas 17:15–18). De Heere Jezus Zelf dankte, bijvoorbeeld voordat Hij de broden uitdeelde (Johannes 6:11). Paulus schrijft: ‘Dankt God in alles; want dit is de wil van God in Christus Jezus over u’ (1 Thessalonicenzen 5:18).",
  refs: [["Psalm 103:2", "Vergeet geen van Zijn weldaden."],
    ["Lukas 17:15–18", "Eén melaatse kwam terug om God te eren."],
    ["Johannes 6:11", "De Heere Jezus dankte voor het brood."],
    ["1 Thessalonicenzen 5:18", "Dankt God in alles."]] };

BR.kernwoorden.evangelie = { n: "Evangelie",
  uitleg: "Evangelie betekent ‘goede boodschap’. Het is het goede nieuws over Jezus Christus, de Zoon van God (Markus 1:1). De kern is ‘dat Christus gestorven is voor onze zonden, naar de Schriften; en dat Hij is begraven, en dat Hij is opgewekt ten derden dage’ (1 Korinthe 15:3–4). De Heere Jezus riep: ‘bekeert u, en gelooft het Evangelie’ (Markus 1:15). Bij Zacheüs zegt Hij waarvoor Hij kwam: ‘om te zoeken en zalig te maken, dat verloren was’ (Lukas 19:10).",
  refs: [["Markus 1:1", "Het begin van het Evangelie van Jezus Christus, de Zoon van God."],
    ["Markus 1:15", "Bekeert u en gelooft het Evangelie."],
    ["Romeinen 1:16", "Het Evangelie is een kracht van God tot zaligheid voor ieder die gelooft."],
    ["Lukas 19:10", "De Zoon des mensen kwam om te zoeken en zalig te maken wat verloren was."]] };
